import sys,subprocess
def check(path,W=1080,H=1350,margin=12):
    d=subprocess.run(['ffmpeg','-loglevel','error','-i',path,'-f','rawvideo','-pix_fmt','rgb24','-'],capture_output=True).stdout
    n=0;pts=[]
    for i in range(0,len(d),3):
        r,g,b=d[i],d[i+1],d[i+2]
        if g>r+margin and g>b+margin:
            n+=1
            if len(pts)<15: pts.append(((i//3)%W,(i//3)//W,(r,g,b)))
    print(path,'greenish px:',n,pts)
for p in sys.argv[1:]: check(p)
EOF
python3 scratch/green.py scratch/f4000.png

